import 'package:flutter/material.dart'; import 'package:shared_preferences/shared_preferences.dart'; import 'screens/login_screen.dart'; import 'screens/home_shell.dart'; void main() async {WidgetsFlutterBinding.ensureInitialized();final p=await SharedPreferences.getInstance();final logged=p.getBool('isLogin')==true;runApp(DvmsApp(logged));} class DvmsApp extends StatelessWidget{final bool logged;const DvmsApp(this.logged,{super.key});@override Widget build(BuildContext c){return MaterialApp(debugShowCheckedModeBanner:false,title:'DVMS',theme:ThemeData(colorScheme:ColorScheme.fromSeed(seedColor:const Color(0xff2458A6)),useMaterial3:true),routes:{'/':(_)=>logged?const HomeShell():const LoginScreen()},initialRoute:'/');}}
